<?php require_once __DIR__.'/../config.php';require_admin();$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT id,nome,email,tipo FROM usuarios WHERE id=?');$s->execute([$id]);$target=$s->fetch();if(!$target){flash('Usuário não encontrado.','danger');redirect('index.php');}$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$nome=trim($_POST['nome']??'');$email=strtolower(trim($_POST['email']??''));$tipo=$_POST['tipo']??'usuario';if($nome==='')$errors[]='Nome obrigatório.';if(!valid_email($email))$errors[]='E-mail inválido.';if(!in_array($tipo,['usuario','administrador'],true))$errors[]='Tipo de conta inválido.';$s=db()->prepare('SELECT id FROM usuarios WHERE email=? AND id<>?');$s->execute([$email,$id]);if($s->fetch())$errors[]='E-mail já utilizado por outra conta.';if(!$errors){$s=db()->prepare('UPDATE usuarios SET nome=?,email=?,tipo=? WHERE id=?');$s->execute([$nome,$email,$tipo,$id]);if($id===user()['id'])refresh_user();flash('Usuário atualizado com sucesso.');redirect('index.php');}$target=array_merge($target,['nome'=>$nome,'email'=>$email,'tipo'=>$tipo]);}$pageTitle='Editar usuário';require __DIR__.'/../includes/header.php'; ?><div class="form-wrap"><form class="form-card" method="post"><h1>Editar usuário</h1><p>Atualize as informações e permissões da conta.</p><?php foreach($errors as $er): ?><div class="alert danger"><?= e($er) ?></div><?php endforeach; ?><input type="hidden" name="csrf" value="<?= csrf() ?>"><div class="field"><label>Nome</label><input name="nome" value="<?= e($target['nome']) ?>" required></div><div class="field"><label>E-mail</label><input type="email" name="email" value="<?= e($target['email']) ?>" required></div><div class="field"><label>Tipo de conta</label><select name="tipo"><option value="usuario" <?= $target['tipo']==='usuario'?'selected':'' ?>>Usuário comum</option><option value="administrador" <?= $target['tipo']==='administrador'?'selected':'' ?>>Administrador</option></select></div><button class="btn">SALVAR ALTERAÇÕES</button><div class="form-foot"><a href="index.php">Voltar ao painel</a></div></form></div><?php require __DIR__.'/../includes/footer.php'; ?>
